mapper.update:
update wx_click_service_log
open_id = #{openId}, service_id = #{serviceId}, service_name = #{serviceName}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
SELECT T.pv as pv, T.uv as uv, T.time as time, sc.name as name FROM ( SELECT service_id, count(*) as pv, count(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y-%m-%d') as time FROM wx_click_service_log WHERE service_id = #{serviceId}
and DATE_FORMAT(create_time,'%Y-%m-%d') = #{time}
GROUP BY time ) T LEFT JOIN ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc ON T.service_id = sc.uuid

SELECT T.pv as pv, T.uv as uv, T.time as time, sc.name as name FROM ( SELECT service_id, count(*) as pv, count(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y-%m') as time FROM wx_click_service_log WHERE service_id = #{serviceId}
and DATE_FORMAT(create_time,'%Y-%m') = #{time}
GROUP BY time ) T LEFT JOIN ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc ON T.service_id = sc.uuid

SELECT T.pv as pv, T.uv as uv, T.time as time, sc.name as name FROM ( SELECT service_id, count(*) as pv, count(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y') as time FROM wx_click_service_log WHERE service_id = #{serviceId}
and DATE_FORMAT(create_time,'%Y') = #{time}
GROUP BY time ) T LEFT JOIN ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc ON T.service_id = sc.uuid

SELECT COALESCE(T.pv, 0) as pv, COALESCE(T.uv, 0) as uv, COALESCE(T.time, #{time}) as time, sc.name as name FROM ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc LEFT JOIN ( SELECT count(*) as pv, count(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y-%m-%d') as time, service_id FROM wx_click_service_log WHERE service_id is not null
and DATE_FORMAT(create_time,'%Y-%m-%d') = #{time}
GROUP BY time,service_id ) T ON T.service_id = sc.uuid ORDER BY pv DESC

