and DATE_FORMAT(create_time,'%Y-%m') = #{time}
GROUP BY time,service_id ) T ON T.service_id = sc.uuid ORDER BY pv DESC

SELECT COALESCE(T.pv, 0) as pv, COALESCE(T.uv, 0) as uv, COALESCE(T.time, #{time}) as time, sc.name as name FROM ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc LEFT JOIN ( SELECT count(*) as pv, count(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y') as time, service_id FROM wx_click_service_log WHERE service_id is not null
and DATE_FORMAT(create_time,'%Y') = #{time}
